{"file_path":"src/parse.js","content":"/**
 * Parsing of the build graph description read from standard input.
 */

/** Raised for every failure that ends the run with status 2. */
export class InputError extends Error {}

const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/** Splits the input into its significant lines, keeping the 1-based numbers. */
function significantLines(text) {
  const raw = text.split('\n')
  if (raw.length > 0 && raw[raw.length - 1] === '') raw.pop()
  const lines = []
  for (let i = 0; i < raw.length; i += 1) {
    const trimmed = raw[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    lines.push({ number: i + 1, words: trimmed.split(/\s+/) })
  }
  return lines
}

/**
 * Reads the description into a graph: a map from name to `{ name, cost, deps }`
 * where `deps` is the sorted list of the names the task depends on.
 */
export function parseGraph(text) {
  const tasks = new Map()
  const edges = []
  const references = []

  for (const { number, words } of significantLines(text)) {
    const directive = words[0]
    if (directive === 'task') {
      if (words.length !== 3) throw new InputError(`line ${number}: expected task <name> <cost>`)
      const [, name, cost] = words
      if (!NAME.test(name)) throw new InputError(`line ${number}: invalid task name ${name}`)
      if (!COST.test(cost)) throw new InputError(`line ${number}: cost must be a non-negative integer`)
      if (tasks.has(name)) throw new InputError(`line ${number}: task ${name} is declared twice`)
      tasks.set(name, { name, cost: Number(cost), deps: new Set() })
    } else if (directive === 'dep') {
      if (words.length < 3) throw new InputError(`line ${number}: expected dep <name> <dependency>...`)
      for (const name of words.slice(1)) {
        if (!NAME.test(name)) throw new InputError(`line ${number}: invalid task name ${name}`)
        references.push(name)
      }
      for (const dependency of words.slice(2)) edges.push([words[1], dependency])
    } else {
      throw new InputError(`line ${number}: unknown directive ${directive}`)
    }
  }

  for (const name of references) {
    if (!tasks.has(name)) throw new InputError(`unknown task ${name}`)
  }
  for (const [name, dependency] of edges) tasks.get(name).deps.add(dependency)

  const graph = new Map()
  for (const name of [...tasks.keys()].sort()) {
    const task = tasks.get(name)
    graph.set(name, { name, cost: task.cost, deps: [...task.deps].sort() })
  }
  return graph
}
"}

