{"file_path":"src/graph.js","content":"/**
 * Analysis of a parsed build graph: cycles, waves, times and priorities.
 */

/** Raised when the graph cannot be scheduled because it contains a cycle. */
export class CycleError extends Error {
  constructor(names) {
    super(`cycle: ${names.join(' -> ')}`)
    this.names = names
  }
}

/**
 * Finds the first cycle a depth-first search meets, walking the tasks and each
 * task's dependencies in ascending name order. Returns the names of the cycle,
 * closed by a repeat of the first, or null when the graph is acyclic.
 */
export function findCycle(graph) {
  const colour = new Map()
  for (const name of graph.keys()) colour.set(name, 'white')

  for (const root of graph.keys()) {
    if (colour.get(root) !== 'white') continue
    const path = [root]
    const frames = [{ name: root, next: 0 }]
    colour.set(root, 'grey')
    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      const deps = graph.get(frame.name).deps
      if (frame.next < deps.length) {
        const dependency = deps[frame.next]
        frame.next += 1
        if (colour.get(dependency) === 'grey') {
          return [...path.slice(path.indexOf(dependency)), dependency]
        }
        if (colour.get(dependency) === 'white') {
          colour.set(dependency, 'grey')
          path.push(dependency)
          frames.push({ name: dependency, next: 0 })
        }
      } else {
        colour.set(frame.name, 'black')
        frames.pop()
        path.pop()
      }
    }
  }
  return null
}

/** Visits every task after its dependencies, without recursion. */
function inDependencyOrder(graph) {
  const done = new Set()
  const order = []
  for (const root of graph.keys()) {
    if (done.has(root)) continue
    const frames = [{ name: root, next: 0 }]
    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      const deps = graph.get(frame.name).deps
      if (frame.next < deps.length) {
        const dependency = deps[frame.next]
        frame.next += 1
        if (!done.has(dependency)) frames.push({ name: dependency, next: 0 })
      } else {
        if (!done.has(frame.name)) {
          done.add(frame.name)
          order.push(frame.name)
        }
        frames.pop()
      }
    }
  }
  return order
}

/**
 * Computes, for every task, its start, its finish and the wave it sits in,
 * along with the makespan of the graph on unlimited workers.
 */
export function analyse(graph) {
  const times = new Map()
  let total = 0
  for (const name of inDependencyOrder(graph)) {
    const task = graph.get(name)
    let start = 0
    let depth = 0
    for (const dependency of task.deps) {
      const before = times.get(dependency)
      if (before.finish > start) start = before.finish
      if (before.depth + 1 > depth) depth = before.depth + 1
    }
    const finish = start + task.cost
    times.set(name, { start, finish, depth })
    if (finish > total) total = finish
  }
  return { times, total }
}

/**
 * The priority of every task: the cost of the longest chain of tasks that
 * begins at it and runs down through the tasks that depend on it.
 */
export function priorities(graph) {
  const dependents = new Map()
  for (const name of graph.keys()) dependents.set(name, [])
  for (const task of graph.values()) {
    for (const dependency of task.deps) dependents.get(dependency).push(task.name)
  }
  const priority = new Map()
  for (const name of inDependencyOrder(graph).reverse()) {
    let below = 0
    for (const dependent of dependents.get(name)) {
      const chain = priority.get(dependent)
      if (chain > below) below = chain
    }
    priority.set(name, graph.get(name).cost + below)
  }
  return priority
}
"}

