/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { InputError, parseGraph } from './parse.js'
import { CycleError, analyse, findCycle } from './graph.js'
import { pack } from './schedule.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'

/** Reads the whole of standard input, treating a closed stream as empty. */
function readInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

/** Checks the arguments and returns the mode and, for `pack`, the worker count. */
function readArguments(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) return { mode: argv[0] }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) throw new InputError('workers must be a positive integer')
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw new InputError(USAGE)
}

/** The lines of the `waves` report. */
function waves(graph) {
  const { times, total } = analyse(graph)
  const byDepth = []
  for (const name of graph.keys()) {
    const { depth } = times.get(name)
    while (byDepth.length <= depth) byDepth.push([])
    byDepth[depth].push(name)
  }
  const lines = byDepth.map((names, depth) => `wave ${depth}: ${names.join(' ')}`)
  lines.push(`total ${total}`)
  return lines
}

/** The lines of the `explain` report. */
function explain(graph) {
  const { times, total } = analyse(graph)
  const lines = []
  for (const name of graph.keys()) {
    const { start, finish, depth } = times.get(name)
    lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
  }
  lines.push(`total ${total}`)
  return lines
}

/** The lines of the `pack` report. */
function schedule(graph, count) {
  const { workers, makespan } = pack(graph, count)
  const lines = workers.map(
    (worker, index) =>
      `worker ${index}:` + worker.runs.map((run) => ` ${run.name}@${run.start}-${run.finish}`).join(''),
  )
  lines.push(`makespan ${makespan}`)
  return lines
}

function main(argv) {
  const { mode, workers } = readArguments(argv)
  const graph = parseGraph(readInput())
  const cycle = findCycle(graph)
  if (cycle !== null) throw new CycleError(cycle)
  if (mode === 'waves') return waves(graph)
  if (mode === 'explain') return explain(graph)
  return schedule(graph, workers)
}

try {
  const lines = main(process.argv.slice(2))
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
} catch (error) {
  if (error instanceof CycleError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(3)
  }
  if (error instanceof InputError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(2)
  }
  throw error
}
"}

